{% extends 'base.html' %}

{% block title %}Create News Article{% endblock %}

{% block content %}
<style>
    textarea.form-control {
        resize: none;
    }
</style>
<div class="container" style="max-width: 900px; margin: 0 auto;">
    <h2 class="mb-4 mt-3">Create News Article</h2>
    <form method="post" enctype="multipart/form-data">
        {% csrf_token %}
        {{ form.non_field_errors }}
        <div class="row">
            <div class="col-md-6">
                <div class="mb-3">
                    {{ form.title.label_tag }}
                    {{ form.title }}
                    {{ form.title.errors }}
                </div>
                <div class="mb-3">
                    {{ form.description.label_tag }}
                    {{ form.description }}
                    {{ form.description.errors }}
                </div>
            </div>
            <div class="col-md-6">
                <div class="mb-3">
                    {{ form.content.label_tag }}
                    {{ form.content }}
                    {{ form.content.errors }}
                </div>
                <div class="mb-3">
                    {{ form.image_link.label_tag }}
                    {{ form.image_link }}
                    {{ form.image_link.errors }}
                </div>
                <div class="mb-3">
                    {{ form.author.label_tag }}
                    {{ form.author }}
                    {{ form.author.errors }}
                </div>
            </div>
        </div>
        <button type="submit" class="btn btn-primary">Submit</button>
    </form>
</div>
{% endblock %}

